<div id="void-review" class="popup-overlay" hidden><div class="popup-content club-modal" role="dialog" aria-modal="true" aria-labelledby="void-review-title"><button type="button" class="popup-close" data-close aria-label="Close"><?= yn_icon('close') ?></button><p class="club-eyebrow">Zonal Treasurer decision</p><h2 id="void-review-title">Review void request</h2><p id="void-review-reference" class="club-sub-note"></p><form id="void-decision-form" method="post" class="club-form"><input type="hidden" name="csrf_token" value="<?= $escape($csrf_token) ?>"><input id="void-review-id" type="hidden" name="void_id"><div class="club-field"><label for="void-remark">Decision remark</label><textarea id="void-remark" name="remark" rows="4" maxlength="1000" required></textarea></div><div class="club-impact" role="note"><strong>Decision effect</strong><p>Approval voids the requested divisional transaction in the future backend. Rejection leaves it unchanged. The division receives the decision remark.</p></div><div class="club-modal-footer"><button type="button" class="club-btn-secondary" data-close>Cancel</button><button type="submit" class="club-btn-secondary" data-decision="rejectvoid">Reject</button><button type="submit" class="club-btn-primary" data-decision="approvevoid">Approve void</button></div></form></div></div>
<script>const voidModal=document.getElementById('void-review'),voidForm=document.getElementById('void-decision-form');document.querySelectorAll('[data-review]').forEach(button=>button.addEventListener('click',()=>{document.getElementById('void-review-id').value=button.dataset.review;document.getElementById('void-review-reference').textContent=button.dataset.division+' - '+button.dataset.reference;document.getElementById('void-remark').value='';voidModal.hidden=false;}));document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>{button.closest('.popup-overlay').hidden=true;}));voidForm.querySelectorAll('[data-decision]').forEach(button=>button.addEventListener('click',()=>{voidForm.action='<?= ROOT ?>/zonaltreasurer/'+button.dataset.decision;}));</script>
